-- Additive risk v1 schema. No existing evidence is rewritten or backfilled.
-- Fail before creating tables if the required per-open scalar ABI is absent,
-- non-text, incorrect at nanosecond precision, or inconsistent across offsets.
SELECT json_extract(CASE WHEN
 typeof(aegis_risk_utc_nano_v1('2026-10-01T12:00:00.000000001Z')) IS 'text'
 AND aegis_risk_utc_nano_v1('2026-10-01T15:30:00.000000001+03:30') IS '2026-10-01T12:00:00.000000001Z'
 AND aegis_risk_utc_nano_v1(NULL) IS NULL
 THEN '{"abi":1}' ELSE 'invalid risk timestamp ABI' END,'$.abi');

CREATE UNIQUE INDEX change_risk_event_scope ON change_events(id,device_id,config_type);
CREATE UNIQUE INDEX change_risk_item_scope ON change_event_items(id,change_event_id,ordinal);

CREATE TABLE change_risk_definitions (
 model_version INTEGER PRIMARY KEY NOT NULL CHECK(model_version>0),
 schema_version INTEGER NOT NULL CHECK(schema_version=1),
 engine_version INTEGER NOT NULL CHECK(engine_version=1),
 materializer_version INTEGER NOT NULL CHECK(materializer_version=1),
 definition_hash TEXT NOT NULL CHECK((typeof(definition_hash)='text' AND length(definition_hash)=64 AND definition_hash NOT GLOB '*[^0-9a-f]*')),
 definition_json TEXT NOT NULL CHECK(json_valid(definition_json) AND json_type(definition_json)='object' AND length(CAST(definition_json AS BLOB))<=65536),
 registered_at TEXT NOT NULL CHECK((typeof(registered_at)='text' AND aegis_risk_utc_nano_v1(registered_at) IS registered_at)),
 UNIQUE(model_version,definition_hash)
);
CREATE TABLE change_risk_assessments (
 id TEXT PRIMARY KEY NOT NULL CHECK((typeof(id)='text' AND length(id)=36 AND id=lower(id) AND substr(id,9,1)='-' AND substr(id,14,1)='-' AND substr(id,19,1)='-' AND substr(id,24,1)='-' AND length(replace(id,'-',''))=32 AND replace(id,'-','') NOT GLOB '*[^0-9a-f]*' AND id<>'00000000-0000-0000-0000-000000000000')),
 event_id TEXT NOT NULL CHECK((typeof(event_id)='text' AND length(event_id)=36 AND event_id=lower(event_id) AND substr(event_id,9,1)='-' AND substr(event_id,14,1)='-' AND substr(event_id,19,1)='-' AND substr(event_id,24,1)='-' AND length(replace(event_id,'-',''))=32 AND replace(event_id,'-','') NOT GLOB '*[^0-9a-f]*' AND event_id<>'00000000-0000-0000-0000-000000000000')),
 device_id TEXT NOT NULL CHECK((typeof(device_id)='text' AND length(device_id)=36 AND device_id=lower(device_id) AND substr(device_id,9,1)='-' AND substr(device_id,14,1)='-' AND substr(device_id,19,1)='-' AND substr(device_id,24,1)='-' AND length(replace(device_id,'-',''))=32 AND replace(device_id,'-','') NOT GLOB '*[^0-9a-f]*' AND device_id<>'00000000-0000-0000-0000-000000000000')),
 config_type TEXT NOT NULL CHECK(config_type IN ('running','startup')),
 revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>0),
 previous_assessment_id TEXT CHECK(previous_assessment_id IS NULL OR (typeof(previous_assessment_id)='text' AND length(previous_assessment_id)=36 AND previous_assessment_id=lower(previous_assessment_id) AND substr(previous_assessment_id,9,1)='-' AND substr(previous_assessment_id,14,1)='-' AND substr(previous_assessment_id,19,1)='-' AND substr(previous_assessment_id,24,1)='-' AND length(replace(previous_assessment_id,'-',''))=32 AND replace(previous_assessment_id,'-','') NOT GLOB '*[^0-9a-f]*' AND previous_assessment_id<>'00000000-0000-0000-0000-000000000000')),
 model_version INTEGER NOT NULL,
 definition_hash TEXT NOT NULL CHECK((typeof(definition_hash)='text' AND length(definition_hash)=64 AND definition_hash NOT GLOB '*[^0-9a-f]*')),
 evidence_schema_version INTEGER NOT NULL CHECK(evidence_schema_version=1),
 evidence_hash TEXT NOT NULL CHECK((typeof(evidence_hash)='text' AND length(evidence_hash)=64 AND evidence_hash NOT GLOB '*[^0-9a-f]*')),
 evidence_json TEXT NOT NULL CHECK(json_valid(evidence_json) AND json_type(evidence_json)='object'),
 source_bindings_json TEXT NOT NULL CHECK(json_valid(source_bindings_json) AND json_type(source_bindings_json)='object'),
 result_hash TEXT NOT NULL CHECK((typeof(result_hash)='text' AND length(result_hash)=64 AND result_hash NOT GLOB '*[^0-9a-f]*')),
 result_json TEXT NOT NULL CHECK(json_valid(result_json) AND json_type(result_json)='object'),
 technical_impact TEXT NOT NULL CHECK(technical_impact IN ('unknown','low','medium','high')),
 known_impact_floor TEXT CHECK(known_impact_floor IS NULL OR known_impact_floor IN ('low','medium','high')),
 evidence_completeness TEXT NOT NULL CHECK(evidence_completeness IN ('complete','partial')),
 review_priority TEXT NOT NULL CHECK(review_priority IN ('normal','elevated','urgent')),
 priority_rank INTEGER NOT NULL CHECK(priority_rank=CASE review_priority WHEN 'normal' THEN 0 WHEN 'elevated' THEN 1 WHEN 'urgent' THEN 2 END),
 total_items INTEGER NOT NULL CHECK(typeof(total_items)='integer' AND total_items BETWEEN 0 AND 10000),
 known_items INTEGER NOT NULL CHECK(typeof(known_items)='integer' AND known_items BETWEEN 0 AND total_items),
 unknown_items INTEGER NOT NULL CHECK(typeof(unknown_items)='integer' AND unknown_items BETWEEN 0 AND total_items),
 distinct_known_categories INTEGER NOT NULL CHECK(typeof(distinct_known_categories)='integer' AND distinct_known_categories BETWEEN 0 AND 13 AND distinct_known_categories<=known_items),
 finding_count INTEGER NOT NULL CHECK(typeof(finding_count)='integer' AND finding_count BETWEEN 1 AND 10016),
 recorded_authorization_status TEXT NOT NULL CHECK(recorded_authorization_status IN ('unaccounted','authorized')),
 authorization_id TEXT REFERENCES change_authorizations(id) ON DELETE RESTRICT,
 recorded_policy_status TEXT NOT NULL CHECK(recorded_policy_status IN ('not_evaluated','pass','violation')),
 policy_evaluation_id TEXT,
 captured_at TEXT NOT NULL CHECK((typeof(captured_at)='text' AND aegis_risk_utc_nano_v1(captured_at) IS captured_at)),
 assessed_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT CHECK((typeof(assessed_by)='text' AND length(assessed_by)=36 AND assessed_by=lower(assessed_by) AND substr(assessed_by,9,1)='-' AND substr(assessed_by,14,1)='-' AND substr(assessed_by,19,1)='-' AND substr(assessed_by,24,1)='-' AND length(replace(assessed_by,'-',''))=32 AND replace(assessed_by,'-','') NOT GLOB '*[^0-9a-f]*' AND assessed_by<>'00000000-0000-0000-0000-000000000000')),
 UNIQUE(event_id,revision), UNIQUE(id,event_id),
 FOREIGN KEY(event_id,device_id,config_type) REFERENCES change_events(id,device_id,config_type) ON DELETE RESTRICT,
 FOREIGN KEY(previous_assessment_id,event_id) REFERENCES change_risk_assessments(id,event_id) ON DELETE RESTRICT,
 FOREIGN KEY(model_version,definition_hash) REFERENCES change_risk_definitions(model_version,definition_hash) ON DELETE RESTRICT,
 FOREIGN KEY(policy_evaluation_id,event_id) REFERENCES change_policy_evaluations(id,event_id) ON DELETE RESTRICT,
 CHECK((revision=1 AND previous_assessment_id IS NULL) OR (revision>1 AND previous_assessment_id IS NOT NULL)),
 CHECK(known_items+unknown_items=total_items),
 CHECK((known_items=0 AND known_impact_floor IS NULL) OR (known_items>0 AND known_impact_floor IS NOT NULL)),
 CHECK((technical_impact='unknown' AND (total_items=0 OR unknown_items>0)) OR (total_items>0 AND unknown_items=0 AND technical_impact IS known_impact_floor)),
 CHECK((recorded_authorization_status='unaccounted' AND authorization_id IS NULL) OR (recorded_authorization_status='authorized' AND authorization_id IS NOT NULL)),
 CHECK((recorded_policy_status='not_evaluated' AND policy_evaluation_id IS NULL) OR (recorded_policy_status IN ('pass','violation') AND policy_evaluation_id IS NOT NULL)),
 CHECK(length(CAST(evidence_json AS BLOB))+length(CAST(source_bindings_json AS BLOB))+length(CAST(result_json AS BLOB))<=4194304)
);
CREATE UNIQUE INDEX change_risk_one_root ON change_risk_assessments(event_id) WHERE revision=1;
CREATE UNIQUE INDEX change_risk_one_successor ON change_risk_assessments(event_id,previous_assessment_id) WHERE previous_assessment_id IS NOT NULL;
CREATE INDEX change_risk_latest ON change_risk_assessments(event_id,revision DESC);
CREATE INDEX change_risk_device_priority ON change_risk_assessments(device_id,priority_rank DESC,captured_at DESC,id);
CREATE INDEX change_risk_policy_ref ON change_risk_assessments(policy_evaluation_id);
CREATE INDEX change_risk_authorization_ref ON change_risk_assessments(authorization_id);
CREATE INDEX change_risk_actor_ref ON change_risk_assessments(assessed_by);
CREATE INDEX change_risk_model_ref ON change_risk_assessments(model_version,definition_hash);
CREATE TABLE change_risk_findings (
 assessment_id TEXT NOT NULL CHECK((typeof(assessment_id)='text' AND length(assessment_id)=36 AND assessment_id=lower(assessment_id) AND substr(assessment_id,9,1)='-' AND substr(assessment_id,14,1)='-' AND substr(assessment_id,19,1)='-' AND substr(assessment_id,24,1)='-' AND length(replace(assessment_id,'-',''))=32 AND replace(assessment_id,'-','') NOT GLOB '*[^0-9a-f]*' AND assessment_id<>'00000000-0000-0000-0000-000000000000')),
 event_id TEXT NOT NULL REFERENCES change_events(id) ON DELETE RESTRICT,
 ordinal INTEGER NOT NULL CHECK(typeof(ordinal)='integer' AND ordinal BETWEEN 0 AND 10015),
 finding_key TEXT NOT NULL CHECK(length(finding_key)<=180),
 rule_id TEXT NOT NULL CHECK(length(rule_id)<=96),
 reason_code TEXT NOT NULL CHECK(reason_code IS rule_id),
 kind TEXT NOT NULL CHECK(kind IN ('technical','governance','uncertainty','summary')),
 subject_kind TEXT NOT NULL CHECK(subject_kind IN ('item','event','authorization','policy')),
 subject_id TEXT NOT NULL CHECK((typeof(subject_id)='text' AND length(subject_id)=36 AND subject_id=lower(subject_id) AND substr(subject_id,9,1)='-' AND substr(subject_id,14,1)='-' AND substr(subject_id,19,1)='-' AND substr(subject_id,24,1)='-' AND length(replace(subject_id,'-',''))=32 AND replace(subject_id,'-','') NOT GLOB '*[^0-9a-f]*' AND subject_id<>'00000000-0000-0000-0000-000000000000')),
 source_item_id TEXT,
 item_ordinal INTEGER,
 impact TEXT CHECK(impact IS NULL OR impact IN ('unknown','low','medium','high')),
 priority_floor TEXT CHECK(priority_floor IS NULL OR priority_floor IN ('normal','elevated','urgent')),
 parameters_json TEXT NOT NULL CHECK(parameters_json='[]'),
 PRIMARY KEY(assessment_id,ordinal), UNIQUE(assessment_id,finding_key),
 FOREIGN KEY(assessment_id,event_id) REFERENCES change_risk_assessments(id,event_id) ON DELETE NO ACTION DEFERRABLE INITIALLY DEFERRED,
 FOREIGN KEY(source_item_id,event_id,item_ordinal) REFERENCES change_event_items(id,change_event_id,ordinal) ON DELETE RESTRICT,
 CHECK(finding_key IS rule_id||':'||subject_kind||':'||subject_id),
 CHECK((subject_kind='item' AND source_item_id IS subject_id AND item_ordinal IS NOT NULL AND typeof(item_ordinal)='integer' AND impact IS NOT NULL)
 OR (subject_kind<>'item' AND source_item_id IS NULL AND item_ordinal IS NULL))
);
CREATE UNIQUE INDEX change_risk_one_item_finding ON change_risk_findings(assessment_id,source_item_id) WHERE source_item_id IS NOT NULL;
CREATE INDEX change_risk_finding_source ON change_risk_findings(source_item_id);

CREATE TRIGGER change_risk_definition_collision BEFORE INSERT ON change_risk_definitions
WHEN EXISTS(SELECT 1 FROM change_risk_definitions WHERE model_version=NEW.model_version)
BEGIN SELECT RAISE(ABORT,'immutable risk definition identity'); END;
CREATE TRIGGER change_risk_finding_collision BEFORE INSERT ON change_risk_findings
WHEN EXISTS(SELECT 1 FROM change_risk_assessments WHERE id=NEW.assessment_id)
 OR EXISTS(SELECT 1 FROM change_risk_findings WHERE assessment_id=NEW.assessment_id AND (ordinal=NEW.ordinal OR finding_key=NEW.finding_key OR (source_item_id IS NOT NULL AND source_item_id=NEW.source_item_id)))
BEGIN SELECT RAISE(ABORT,'sealed or duplicate risk finding'); END;
CREATE TRIGGER change_risk_definitions_no_update BEFORE UPDATE ON change_risk_definitions
BEGIN SELECT RAISE(ABORT,'immutable risk evidence'); END;
CREATE TRIGGER change_risk_definitions_no_delete BEFORE DELETE ON change_risk_definitions
BEGIN SELECT RAISE(ABORT,'immutable risk evidence'); END;
CREATE TRIGGER change_risk_assessments_no_update BEFORE UPDATE ON change_risk_assessments
BEGIN SELECT RAISE(ABORT,'immutable risk evidence'); END;
CREATE TRIGGER change_risk_assessments_no_delete BEFORE DELETE ON change_risk_assessments
BEGIN SELECT RAISE(ABORT,'immutable risk evidence'); END;
CREATE TRIGGER change_risk_findings_no_update BEFORE UPDATE ON change_risk_findings
BEGIN SELECT RAISE(ABORT,'immutable risk evidence'); END;
CREATE TRIGGER change_risk_findings_no_delete BEFORE DELETE ON change_risk_findings
BEGIN SELECT RAISE(ABORT,'immutable risk evidence'); END;

CREATE TRIGGER change_risk_header_seal BEFORE INSERT ON change_risk_assessments BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM change_risk_assessments WHERE id=NEW.id OR (event_id=NEW.event_id AND revision=NEW.revision) OR (event_id=NEW.event_id AND previous_assessment_id=NEW.previous_assessment_id AND NEW.previous_assessment_id IS NOT NULL)) THEN RAISE(ABORT,'immutable risk assessment identity') END;
 SELECT CASE WHEN NEW.revision IS NOT (SELECT COALESCE(MAX(revision),0)+1 FROM change_risk_assessments WHERE event_id=NEW.event_id)
 OR NEW.previous_assessment_id IS NOT (SELECT id FROM change_risk_assessments WHERE event_id=NEW.event_id ORDER BY revision DESC LIMIT 1)
 THEN RAISE(ABORT,'stale risk predecessor') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM change_risk_assessments WHERE id=NEW.previous_assessment_id AND definition_hash=NEW.definition_hash AND evidence_hash=NEW.evidence_hash)
 THEN RAISE(ABORT,'unchanged latest risk fingerprint') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM change_risk_definitions WHERE model_version=NEW.model_version AND definition_hash=NEW.definition_hash AND schema_version=1 AND engine_version=1 AND materializer_version=1)
 THEN RAISE(ABORT,'unsupported risk model') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM change_events WHERE id=NEW.event_id AND device_id=NEW.device_id AND config_type=NEW.config_type AND analysis_version=1 AND analyzed_at IS NOT NULL AND item_count=NEW.total_items AND authorization_status=NEW.recorded_authorization_status AND policy_status=NEW.recorded_policy_status)
 THEN RAISE(ABORT,'invalid risk source scope') END;
 SELECT CASE WHEN NOT (json_type(NEW.evidence_json,'$') IS 'object' AND (SELECT group_concat(key,',') FROM json_each(NEW.evidence_json,'$')) IS 'schema_version,event,items,authorization,policy,eligibility' AND json_type(NEW.evidence_json,'$.schema_version') IN ('integer') AND (json_type(NEW.evidence_json,'$.event') IS 'object' AND (SELECT group_concat(key,',') FROM json_each(NEW.evidence_json,'$.event')) IS 'event_id,device_id,config_type,from_backup_id,to_backup_id,detected_at,created_at,analysis_version,item_count,added_lines,removed_lines,analyzed_at' AND json_type(NEW.evidence_json,'$.event.event_id') IN ('text') AND json_type(NEW.evidence_json,'$.event.device_id') IN ('text') AND json_type(NEW.evidence_json,'$.event.config_type') IN ('text') AND json_type(NEW.evidence_json,'$.event.from_backup_id') IN ('text') AND json_type(NEW.evidence_json,'$.event.to_backup_id') IN ('text') AND json_type(NEW.evidence_json,'$.event.detected_at') IN ('text') AND json_type(NEW.evidence_json,'$.event.created_at') IN ('text') AND json_type(NEW.evidence_json,'$.event.analysis_version') IN ('integer') AND json_type(NEW.evidence_json,'$.event.item_count') IN ('integer') AND json_type(NEW.evidence_json,'$.event.added_lines') IN ('integer') AND json_type(NEW.evidence_json,'$.event.removed_lines') IN ('integer') AND json_type(NEW.evidence_json,'$.event.analyzed_at') IN ('text')) AND (json_type(NEW.evidence_json,'$.items') IS 'array' AND NOT EXISTS(SELECT 1 FROM json_each(NEW.evidence_json,'$.items') risk_shape_1 WHERE NOT ((json_type(risk_shape_1.value,'$') IS 'object' AND (SELECT group_concat(key,',') FROM json_each(risk_shape_1.value,'$')) IS 'item_id,ordinal,operation,category,subcategory,classification_rule,classification_version,sensitive,created_at,classified_at' AND json_type(risk_shape_1.value,'$.item_id') IN ('text') AND json_type(risk_shape_1.value,'$.ordinal') IN ('integer') AND json_type(risk_shape_1.value,'$.operation') IN ('text') AND json_type(risk_shape_1.value,'$.category') IN ('text') AND json_type(risk_shape_1.value,'$.subcategory') IN ('text') AND json_type(risk_shape_1.value,'$.classification_rule') IN ('text') AND json_type(risk_shape_1.value,'$.classification_version') IN ('integer') AND json_type(risk_shape_1.value,'$.sensitive') IN ('true','false') AND json_type(risk_shape_1.value,'$.created_at') IN ('text') AND json_type(risk_shape_1.value,'$.classified_at') IN ('text'))))) AND (json_type(NEW.evidence_json,'$.authorization') IS 'object' AND (SELECT group_concat(key,',') FROM json_each(NEW.evidence_json,'$.authorization')) IS 'recorded_status,link,ticket,history' AND json_type(NEW.evidence_json,'$.authorization.recorded_status') IN ('text') AND (json_type(NEW.evidence_json,'$.authorization.link') IS 'null' OR ((json_type(NEW.evidence_json,'$.authorization.link') IS 'object' AND (SELECT group_concat(key,',') FROM json_each(NEW.evidence_json,'$.authorization.link')) IS 'event_id,authorization_id,linked_by,linked_at,attestation' AND json_type(NEW.evidence_json,'$.authorization.link.event_id') IN ('text') AND json_type(NEW.evidence_json,'$.authorization.link.authorization_id') IN ('text') AND json_type(NEW.evidence_json,'$.authorization.link.linked_by') IN ('text') AND json_type(NEW.evidence_json,'$.authorization.link.linked_at') IN ('text') AND json_type(NEW.evidence_json,'$.authorization.link.attestation') IN ('text')))) AND (json_type(NEW.evidence_json,'$.authorization.ticket') IS 'null' OR ((json_type(NEW.evidence_json,'$.authorization.ticket') IS 'object' AND (SELECT group_concat(key,',') FROM json_each(NEW.evidence_json,'$.authorization.ticket')) IS 'id,device_id,config_type,status,allowed_categories,window_start,window_end,requested_by,requested_at,approved_by,approved_at,rejected_by,rejected_at,revoked_by,revoked_at,created_at' AND json_type(NEW.evidence_json,'$.authorization.ticket.id') IN ('text') AND json_type(NEW.evidence_json,'$.authorization.ticket.device_id') IN ('text') AND json_type(NEW.evidence_json,'$.authorization.ticket.config_type') IN ('text') AND json_type(NEW.evidence_json,'$.authorization.ticket.status') IN ('text') AND (json_type(NEW.evidence_json,'$.authorization.ticket.allowed_categories') IS 'array' AND NOT EXISTS(SELECT 1 FROM json_each(NEW.evidence_json,'$.authorization.ticket.allowed_categories') risk_shape_2 WHERE NOT (risk_shape_2.type IN ('text')))) AND json_type(NEW.evidence_json,'$.authorization.ticket.window_start') IN ('text') AND json_type(NEW.evidence_json,'$.authorization.ticket.window_end') IN ('text') AND json_type(NEW.evidence_json,'$.authorization.ticket.requested_by') IN ('text') AND json_type(NEW.evidence_json,'$.authorization.ticket.requested_at') IN ('text') AND json_type(NEW.evidence_json,'$.authorization.ticket.approved_by') IN ('text') AND json_type(NEW.evidence_json,'$.authorization.ticket.approved_at') IN ('text') AND json_type(NEW.evidence_json,'$.authorization.ticket.rejected_by') IN ('text','null') AND json_type(NEW.evidence_json,'$.authorization.ticket.rejected_at') IN ('text','null') AND json_type(NEW.evidence_json,'$.authorization.ticket.revoked_by') IN ('text','null') AND json_type(NEW.evidence_json,'$.authorization.ticket.revoked_at') IN ('text','null') AND json_type(NEW.evidence_json,'$.authorization.ticket.created_at') IN ('text')))) AND (json_type(NEW.evidence_json,'$.authorization.history') IS 'array' AND NOT EXISTS(SELECT 1 FROM json_each(NEW.evidence_json,'$.authorization.history') risk_shape_3 WHERE NOT ((json_type(risk_shape_3.value,'$') IS 'object' AND (SELECT group_concat(key,',') FROM json_each(risk_shape_3.value,'$')) IS 'id,action,actor_id,occurred_at,event_id' AND json_type(risk_shape_3.value,'$.id') IN ('text') AND json_type(risk_shape_3.value,'$.action') IN ('text') AND json_type(risk_shape_3.value,'$.actor_id') IN ('text') AND json_type(risk_shape_3.value,'$.occurred_at') IN ('text') AND json_type(risk_shape_3.value,'$.event_id') IN ('text','null')))))) AND (json_type(NEW.evidence_json,'$.policy') IS 'object' AND (SELECT group_concat(key,',') FROM json_each(NEW.evidence_json,'$.policy')) IS 'recorded_status,final' AND json_type(NEW.evidence_json,'$.policy.recorded_status') IN ('text') AND (json_type(NEW.evidence_json,'$.policy.final') IS 'null' OR ((json_type(NEW.evidence_json,'$.policy.final') IS 'object' AND (SELECT group_concat(key,',') FROM json_each(NEW.evidence_json,'$.policy.final')) IS 'id,event_id,policy_set_id,definition_hash,definition,engine_version,result,evaluated_by,evaluated_at,total_items,allowed_count,denied_count,uncovered_count,items' AND json_type(NEW.evidence_json,'$.policy.final.id') IN ('text') AND json_type(NEW.evidence_json,'$.policy.final.event_id') IN ('text') AND json_type(NEW.evidence_json,'$.policy.final.policy_set_id') IN ('text') AND json_type(NEW.evidence_json,'$.policy.final.definition_hash') IN ('text') AND (json_type(NEW.evidence_json,'$.policy.final.definition') IS 'object' AND (SELECT group_concat(key,',') FROM json_each(NEW.evidence_json,'$.policy.final.definition')) IS 'engine_version,device_id,config_type,rules' AND json_type(NEW.evidence_json,'$.policy.final.definition.engine_version') IN ('integer') AND json_type(NEW.evidence_json,'$.policy.final.definition.device_id') IN ('text') AND json_type(NEW.evidence_json,'$.policy.final.definition.config_type') IN ('text') AND (json_type(NEW.evidence_json,'$.policy.final.definition.rules') IS 'array' AND NOT EXISTS(SELECT 1 FROM json_each(NEW.evidence_json,'$.policy.final.definition.rules') risk_shape_4 WHERE NOT ((json_type(risk_shape_4.value,'$') IS 'object' AND (SELECT group_concat(key,',') FROM json_each(risk_shape_4.value,'$')) IS 'category,operation,decision' AND json_type(risk_shape_4.value,'$.category') IN ('text') AND json_type(risk_shape_4.value,'$.operation') IN ('text') AND json_type(risk_shape_4.value,'$.decision') IN ('text')))))) AND json_type(NEW.evidence_json,'$.policy.final.engine_version') IN ('integer') AND json_type(NEW.evidence_json,'$.policy.final.result') IN ('text') AND json_type(NEW.evidence_json,'$.policy.final.evaluated_by') IN ('text') AND json_type(NEW.evidence_json,'$.policy.final.evaluated_at') IN ('text') AND json_type(NEW.evidence_json,'$.policy.final.total_items') IN ('integer') AND json_type(NEW.evidence_json,'$.policy.final.allowed_count') IN ('integer') AND json_type(NEW.evidence_json,'$.policy.final.denied_count') IN ('integer') AND json_type(NEW.evidence_json,'$.policy.final.uncovered_count') IN ('integer') AND (json_type(NEW.evidence_json,'$.policy.final.items') IS 'array' AND NOT EXISTS(SELECT 1 FROM json_each(NEW.evidence_json,'$.policy.final.items') risk_shape_5 WHERE NOT ((json_type(risk_shape_5.value,'$') IS 'object' AND (SELECT group_concat(key,',') FROM json_each(risk_shape_5.value,'$')) IS 'item_id,ordinal,category,operation,decision,matched_rule_key' AND json_type(risk_shape_5.value,'$.item_id') IN ('text') AND json_type(risk_shape_5.value,'$.ordinal') IN ('integer') AND json_type(risk_shape_5.value,'$.category') IN ('text') AND json_type(risk_shape_5.value,'$.operation') IN ('text') AND json_type(risk_shape_5.value,'$.decision') IN ('text') AND json_type(risk_shape_5.value,'$.matched_rule_key') IN ('text'))))))))) AND (json_type(NEW.evidence_json,'$.eligibility') IS 'object' AND (SELECT group_concat(key,',') FROM json_each(NEW.evidence_json,'$.eligibility')) IS 'persistable,reasons' AND json_type(NEW.evidence_json,'$.eligibility.persistable') IN ('true') AND (json_type(NEW.evidence_json,'$.eligibility.reasons') IS 'array' AND NOT EXISTS(SELECT 1 FROM json_each(NEW.evidence_json,'$.eligibility.reasons') risk_shape_6 WHERE NOT (risk_shape_6.type IN ('text')))))) OR NEW.evidence_json IS NOT json(NEW.evidence_json) THEN RAISE(ABORT,'invalid closed risk JSON shape') END;
