 SELECT CASE WHEN NEW.recorded_authorization_status='authorized' AND NOT EXISTS(SELECT 1 FROM change_event_authorizations l WHERE l.event_id=NEW.event_id AND l.authorization_id=NEW.authorization_id AND NOT (json_extract(NEW.evidence_json,'$.authorization.link.event_id') IS NOT l.event_id OR json_extract(NEW.evidence_json,'$.authorization.link.authorization_id') IS NOT l.authorization_id OR json_extract(NEW.evidence_json,'$.authorization.link.linked_by') IS NOT l.linked_by OR json_extract(NEW.evidence_json,'$.authorization.link.attestation') IS NOT l.attestation OR json_extract(NEW.source_bindings_json,'$.governance.link.event_id') IS NOT l.event_id OR json_extract(NEW.source_bindings_json,'$.governance.link.authorization_id') IS NOT l.authorization_id OR json_extract(NEW.source_bindings_json,'$.governance.link.linked_at') IS NOT l.linked_at OR aegis_risk_utc_nano_v1(l.linked_at) IS NOT json_extract(NEW.evidence_json,'$.authorization.link.linked_at') OR json_extract(NEW.evidence_json,'$.authorization.link.linked_at')>NEW.captured_at)) THEN RAISE(ABORT,'authorized risk link binding') END;
 SELECT CASE WHEN NEW.recorded_authorization_status='authorized' AND NOT EXISTS(SELECT 1 FROM change_authorizations t WHERE t.id=NEW.authorization_id AND t.device_id=NEW.device_id AND t.config_type=NEW.config_type AND NOT (json_extract(NEW.evidence_json,'$.authorization.ticket.id') IS NOT t.id OR json_extract(NEW.evidence_json,'$.authorization.ticket.device_id') IS NOT t.device_id OR json_extract(NEW.evidence_json,'$.authorization.ticket.config_type') IS NOT t.config_type OR json_extract(NEW.evidence_json,'$.authorization.ticket.status') IS NOT t.status OR json_extract(NEW.evidence_json,'$.authorization.ticket.requested_by') IS NOT t.requested_by OR json_extract(NEW.evidence_json,'$.authorization.ticket.approved_by') IS NOT t.approved_by OR json_extract(NEW.evidence_json,'$.authorization.ticket.rejected_by') IS NOT t.rejected_by OR json_extract(NEW.evidence_json,'$.authorization.ticket.revoked_by') IS NOT t.revoked_by OR t.status NOT IN ('approved','revoked') OR json_extract(NEW.source_bindings_json,'$.governance.ticket.authorization_id') IS NOT t.id OR json_extract(NEW.source_bindings_json,'$.governance.ticket.window_start') IS NOT t.window_start OR aegis_risk_utc_nano_v1(t.window_start) IS NOT json_extract(NEW.evidence_json,'$.authorization.ticket.window_start') OR json_extract(NEW.source_bindings_json,'$.governance.ticket.window_end') IS NOT t.window_end OR aegis_risk_utc_nano_v1(t.window_end) IS NOT json_extract(NEW.evidence_json,'$.authorization.ticket.window_end') OR json_extract(NEW.source_bindings_json,'$.governance.ticket.requested_at') IS NOT t.requested_at OR aegis_risk_utc_nano_v1(t.requested_at) IS NOT json_extract(NEW.evidence_json,'$.authorization.ticket.requested_at') OR json_extract(NEW.evidence_json,'$.authorization.ticket.requested_at')>NEW.captured_at OR json_extract(NEW.source_bindings_json,'$.governance.ticket.approved_at') IS NOT t.approved_at OR aegis_risk_utc_nano_v1(t.approved_at) IS NOT json_extract(NEW.evidence_json,'$.authorization.ticket.approved_at') OR json_extract(NEW.evidence_json,'$.authorization.ticket.approved_at')>NEW.captured_at OR json_extract(NEW.source_bindings_json,'$.governance.ticket.rejected_at') IS NOT t.rejected_at OR aegis_risk_utc_nano_v1(t.rejected_at) IS NOT json_extract(NEW.evidence_json,'$.authorization.ticket.rejected_at') OR (t.rejected_at IS NOT NULL AND json_extract(NEW.evidence_json,'$.authorization.ticket.rejected_at') > NEW.captured_at) OR json_extract(NEW.source_bindings_json,'$.governance.ticket.revoked_at') IS NOT t.revoked_at OR aegis_risk_utc_nano_v1(t.revoked_at) IS NOT json_extract(NEW.evidence_json,'$.authorization.ticket.revoked_at') OR (t.revoked_at IS NOT NULL AND json_extract(NEW.evidence_json,'$.authorization.ticket.revoked_at') > NEW.captured_at) OR json_extract(NEW.source_bindings_json,'$.governance.ticket.created_at') IS NOT t.created_at OR aegis_risk_utc_nano_v1(t.created_at) IS NOT json_extract(NEW.evidence_json,'$.authorization.ticket.created_at') OR json_extract(NEW.evidence_json,'$.authorization.ticket.created_at')>NEW.captured_at OR json_array_length(NEW.evidence_json,'$.authorization.ticket.allowed_categories') IS NOT json_array_length(t.allowed_categories_json) OR EXISTS(SELECT 1 FROM json_each(t.allowed_categories_json) sc WHERE NOT EXISTS(SELECT 1 FROM json_each(NEW.evidence_json,'$.authorization.ticket.allowed_categories') cc WHERE cc.value IS sc.value)) OR EXISTS(SELECT 1 FROM json_each(NEW.evidence_json,'$.authorization.ticket.allowed_categories') cc WHERE cc.key>0 AND cc.value <= json_extract(NEW.evidence_json,'$.authorization.ticket.allowed_categories['||(cc.key-1)||']')))) THEN RAISE(ABORT,'risk ticket binding') END;
 SELECT CASE WHEN NEW.recorded_authorization_status='authorized' AND (json_array_length(NEW.evidence_json,'$.authorization.history') IS NOT (SELECT COUNT(*) FROM change_authorization_history WHERE authorization_id=NEW.authorization_id) OR json_array_length(NEW.source_bindings_json,'$.governance.history') IS NOT json_array_length(NEW.evidence_json,'$.authorization.history')) THEN RAISE(ABORT,'risk authorization history count') END;
 SELECT CASE WHEN NEW.recorded_authorization_status='authorized' AND EXISTS(SELECT 1 FROM json_each(NEW.evidence_json,'$.authorization.history') eh LEFT JOIN json_each(NEW.source_bindings_json,'$.governance.history') bh ON bh.key=eh.key LEFT JOIN change_authorization_history sh ON sh.id=json_extract(eh.value,'$.id') AND sh.authorization_id=NEW.authorization_id WHERE sh.id IS NULL OR json_extract(eh.value,'$.id') IS NOT sh.id OR json_extract(eh.value,'$.action') IS NOT sh.action OR json_extract(eh.value,'$.event_id') IS NOT sh.event_id OR json_extract(eh.value,'$.actor_id') IS NOT sh.actor_user_id OR json_extract(bh.value,'$.id') IS NOT sh.id OR json_extract(bh.value,'$.action') IS NOT sh.action OR json_extract(bh.value,'$.event_id') IS NOT sh.event_id OR json_extract(bh.value,'$.occurred_at') IS NOT sh.occurred_at OR aegis_risk_utc_nano_v1(sh.occurred_at) IS NOT json_extract(eh.value,'$.occurred_at') OR json_extract(eh.value,'$.occurred_at')>NEW.captured_at) THEN RAISE(ABORT,'risk authorization history binding') END;
 SELECT CASE WHEN NEW.recorded_authorization_status='authorized' AND (SELECT COUNT(DISTINCT json_extract(value,'$.id')) FROM json_each(NEW.evidence_json,'$.authorization.history')) IS NOT json_array_length(NEW.evidence_json,'$.authorization.history') THEN RAISE(ABORT,'duplicate risk authorization history') END;
 SELECT CASE WHEN NEW.recorded_policy_status='not_evaluated' AND (json_extract(NEW.evidence_json,'$.policy.final') IS NOT NULL OR json_extract(NEW.source_bindings_json,'$.governance.policy') IS NOT NULL OR EXISTS(SELECT 1 FROM change_policy_evaluations WHERE event_id=NEW.event_id)) THEN RAISE(ABORT,'unevaluated risk policy binding') END;
 SELECT CASE WHEN NEW.recorded_policy_status<>'not_evaluated' AND NOT EXISTS(SELECT 1 FROM change_policy_evaluations p WHERE p.id=NEW.policy_evaluation_id AND p.event_id=NEW.event_id AND NOT (json_extract(NEW.evidence_json,'$.policy.final.id') IS NOT p.id OR json_extract(NEW.evidence_json,'$.policy.final.event_id') IS NOT p.event_id OR json_extract(NEW.evidence_json,'$.policy.final.policy_set_id') IS NOT p.policy_set_id OR json_extract(NEW.evidence_json,'$.policy.final.engine_version') IS NOT p.engine_version OR json_extract(NEW.evidence_json,'$.policy.final.result') IS NOT p.result OR json_extract(NEW.evidence_json,'$.policy.final.evaluated_by') IS NOT p.evaluated_by OR json_extract(NEW.evidence_json,'$.policy.final.total_items') IS NOT p.total_items OR json_extract(NEW.evidence_json,'$.policy.final.allowed_count') IS NOT p.allowed_count OR json_extract(NEW.evidence_json,'$.policy.final.denied_count') IS NOT p.denied_count OR json_extract(NEW.evidence_json,'$.policy.final.uncovered_count') IS NOT p.uncovered_count OR json_extract(NEW.evidence_json,'$.policy.final.definition_hash') IS NOT p.policy_definition_hash OR json_extract(NEW.evidence_json,'$.policy.final.definition') IS NOT p.policy_definition_snapshot OR json_extract(NEW.source_bindings_json,'$.governance.policy.evaluation_id') IS NOT p.id OR json_extract(NEW.source_bindings_json,'$.governance.policy.evaluated_at') IS NOT p.evaluated_at OR aegis_risk_utc_nano_v1(p.evaluated_at) IS NOT json_extract(NEW.evidence_json,'$.policy.final.evaluated_at') OR json_extract(NEW.evidence_json,'$.policy.final.evaluated_at')>NEW.captured_at OR p.total_items IS NOT NEW.total_items OR p.result IS NOT NEW.recorded_policy_status OR json_array_length(NEW.evidence_json,'$.policy.final.items') IS NOT p.total_items OR (SELECT COUNT(*) FROM change_policy_evaluation_items WHERE evaluation_id=p.id) IS NOT p.total_items)) THEN RAISE(ABORT,'risk final policy binding') END;
 SELECT CASE WHEN NEW.recorded_policy_status<>'not_evaluated' AND EXISTS(SELECT 1 FROM json_each(NEW.evidence_json,'$.policy.final.items') pi LEFT JOIN change_policy_evaluation_items sp ON sp.evaluation_id=NEW.policy_evaluation_id AND sp.ordinal=pi.key WHERE sp.evaluation_id IS NULL OR json_extract(pi.value,'$.ordinal') IS NOT sp.ordinal OR json_extract(pi.value,'$.category') IS NOT sp.category OR json_extract(pi.value,'$.operation') IS NOT sp.operation OR json_extract(pi.value,'$.decision') IS NOT sp.decision OR json_extract(pi.value,'$.matched_rule_key') IS NOT sp.matched_rule_key OR json_extract(pi.value,'$.item_id') IS NOT sp.change_event_item_id OR json_extract(pi.value,'$.ordinal') IS NOT pi.key OR sp.event_id IS NOT NEW.event_id) THEN RAISE(ABORT,'risk policy item binding') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM change_risk_findings WHERE assessment_id=NEW.id AND rule_id='risk.evidence.no_items.v1' AND subject_kind<>'item') IS NOT CASE WHEN NEW.total_items=0 THEN 1 ELSE 0 END THEN RAISE(ABORT,'risk required governance finding') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM change_risk_findings WHERE assessment_id=NEW.id AND rule_id='risk.gov.unaccounted.v1' AND subject_kind<>'item') IS NOT CASE WHEN NEW.recorded_authorization_status='unaccounted' THEN 1 ELSE 0 END THEN RAISE(ABORT,'risk required governance finding') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM change_risk_findings WHERE assessment_id=NEW.id AND rule_id='risk.gov.authorized_recorded.v1' AND subject_kind<>'item') IS NOT CASE WHEN NEW.recorded_authorization_status='authorized' THEN 1 ELSE 0 END THEN RAISE(ABORT,'risk required governance finding') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM change_risk_findings WHERE assessment_id=NEW.id AND rule_id='risk.gov.authorization_revoked.v1' AND subject_kind<>'item') IS NOT CASE WHEN json_extract(NEW.evidence_json,'$.authorization.ticket.status')='revoked' THEN 1 ELSE 0 END THEN RAISE(ABORT,'risk required governance finding') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM change_risk_findings WHERE assessment_id=NEW.id AND rule_id='risk.gov.policy_not_evaluated.v1' AND subject_kind<>'item') IS NOT CASE WHEN NEW.recorded_policy_status='not_evaluated' THEN 1 ELSE 0 END THEN RAISE(ABORT,'risk required governance finding') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM change_risk_findings WHERE assessment_id=NEW.id AND rule_id='risk.gov.policy_pass_recorded.v1' AND subject_kind<>'item') IS NOT CASE WHEN NEW.recorded_policy_status='pass' THEN 1 ELSE 0 END THEN RAISE(ABORT,'risk required governance finding') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM change_risk_findings WHERE assessment_id=NEW.id AND rule_id='risk.gov.policy_violation.v1' AND subject_kind<>'item') IS NOT CASE WHEN NEW.recorded_policy_status='violation' THEN 1 ELSE 0 END THEN RAISE(ABORT,'risk required governance finding') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM change_risk_findings WHERE assessment_id=NEW.id AND rule_id='risk.evidence.policy_uncovered.v1' AND subject_kind<>'item') IS NOT CASE WHEN json_extract(NEW.evidence_json,'$.policy.final.uncovered_count')>0 THEN 1 ELSE 0 END THEN RAISE(ABORT,'risk required governance finding') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM change_risk_findings WHERE assessment_id=NEW.id AND rule_id='risk.summary.multiple_categories.v1' AND subject_kind<>'item') IS NOT CASE WHEN NEW.distinct_known_categories>1 THEN 1 ELSE 0 END THEN RAISE(ABORT,'risk required governance finding') END;
 SELECT CASE WHEN (SELECT COUNT(*) FROM change_risk_findings WHERE assessment_id=NEW.id AND rule_id='risk.summary.normal_review.v1' AND subject_kind<>'item') IS NOT CASE WHEN NEW.review_priority='normal' THEN 1 ELSE 0 END THEN RAISE(ABORT,'risk required governance finding') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM change_risk_findings f WHERE f.assessment_id=NEW.id AND f.subject_kind<>'item' AND NOT ((f.rule_id='risk.evidence.no_items.v1' AND f.kind='uncertainty' AND f.subject_kind='event' AND f.subject_id IS NEW.event_id AND f.impact IS 'unknown' AND f.priority_floor IS 'elevated') OR (f.rule_id='risk.gov.unaccounted.v1' AND f.kind='governance' AND f.subject_kind='event' AND f.subject_id IS NEW.event_id AND f.impact IS NULL AND f.priority_floor IS 'elevated') OR (f.rule_id='risk.gov.authorized_recorded.v1' AND f.kind='governance' AND f.subject_kind='authorization' AND f.subject_id IS NEW.authorization_id AND f.impact IS NULL AND f.priority_floor IS NULL) OR (f.rule_id='risk.gov.authorization_revoked.v1' AND f.kind='governance' AND f.subject_kind='authorization' AND f.subject_id IS NEW.authorization_id AND f.impact IS NULL AND f.priority_floor IS 'urgent') OR (f.rule_id='risk.gov.policy_not_evaluated.v1' AND f.kind='governance' AND f.subject_kind='event' AND f.subject_id IS NEW.event_id AND f.impact IS NULL AND f.priority_floor IS 'elevated') OR (f.rule_id='risk.gov.policy_pass_recorded.v1' AND f.kind='governance' AND f.subject_kind='policy' AND f.subject_id IS NEW.policy_evaluation_id AND f.impact IS NULL AND f.priority_floor IS NULL) OR (f.rule_id='risk.gov.policy_violation.v1' AND f.kind='governance' AND f.subject_kind='policy' AND f.subject_id IS NEW.policy_evaluation_id AND f.impact IS NULL AND f.priority_floor IS 'urgent') OR (f.rule_id='risk.evidence.policy_uncovered.v1' AND f.kind='uncertainty' AND f.subject_kind='policy' AND f.subject_id IS NEW.policy_evaluation_id AND f.impact IS NULL AND f.priority_floor IS 'urgent') OR (f.rule_id='risk.summary.multiple_categories.v1' AND f.kind='summary' AND f.subject_kind='event' AND f.subject_id IS NEW.event_id AND f.impact IS NULL AND f.priority_floor IS NULL) OR (f.rule_id='risk.summary.normal_review.v1' AND f.kind='summary' AND f.subject_kind='event' AND f.subject_id IS NEW.event_id AND f.impact IS NULL AND f.priority_floor IS NULL))) THEN RAISE(ABORT,'invalid risk governance finding') END;
 SELECT CASE WHEN NEW.evidence_completeness IS NOT CASE WHEN NEW.total_items=0 OR NEW.unknown_items>0 OR NEW.recorded_authorization_status='unaccounted' OR NEW.recorded_policy_status='not_evaluated' OR COALESCE(json_extract(NEW.evidence_json,'$.policy.final.uncovered_count'),0)>0 THEN 'partial' ELSE 'complete' END THEN RAISE(ABORT,'risk completeness projection') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM change_risk_findings a JOIN change_risk_findings z ON z.assessment_id=a.assessment_id AND z.ordinal=a.ordinal+1 WHERE a.assessment_id=NEW.id AND (CASE a.kind WHEN 'technical' THEN 0 WHEN 'governance' THEN 1 WHEN 'uncertainty' THEN 2 ELSE 3 END,COALESCE(a.item_ordinal,-1),a.rule_id,a.subject_kind,a.subject_id,a.reason_code)>(CASE z.kind WHEN 'technical' THEN 0 WHEN 'governance' THEN 1 WHEN 'uncertainty' THEN 2 ELSE 3 END,COALESCE(z.item_ordinal,-1),z.rule_id,z.subject_kind,z.subject_id,z.reason_code)) THEN RAISE(ABORT,'risk finding order') END;
 SELECT CASE WHEN NEW.recorded_authorization_status='authorized' AND (json_extract(NEW.evidence_json,'$.authorization.ticket.requested_by') IS json_extract(NEW.evidence_json,'$.authorization.ticket.approved_by') OR json_extract(NEW.evidence_json,'$.authorization.ticket.requested_by') IS json_extract(NEW.evidence_json,'$.authorization.link.linked_by') OR json_extract(NEW.evidence_json,'$.authorization.ticket.window_start')>=json_extract(NEW.evidence_json,'$.authorization.ticket.window_end') OR json_extract(NEW.evidence_json,'$.event.detected_at')<json_extract(NEW.evidence_json,'$.authorization.ticket.window_start') OR json_extract(NEW.evidence_json,'$.event.detected_at')>=json_extract(NEW.evidence_json,'$.authorization.ticket.window_end') OR json_extract(NEW.evidence_json,'$.authorization.ticket.requested_at')>json_extract(NEW.evidence_json,'$.authorization.ticket.approved_at') OR json_extract(NEW.evidence_json,'$.authorization.ticket.approved_at')>json_extract(NEW.evidence_json,'$.authorization.link.linked_at') OR json_extract(NEW.evidence_json,'$.authorization.ticket.revoked_at')<json_extract(NEW.evidence_json,'$.authorization.link.linked_at')) THEN RAISE(ABORT,'risk authorization chronology') END;
END;
CREATE TRIGGER change_risk_definition_shape BEFORE INSERT ON change_risk_definitions BEGIN
 SELECT CASE WHEN NEW.definition_json IS NOT json_set('{"model_version":1,"schema_version":1,"engine_version":1,"materializer_version":1,"accepted_analysis_versions":[1],"accepted_classification_versions":[1],"aggregation":{"impact_mode":"unknown_dominates_with_known_floor","priority_mode":"maximum_floor","finding_order":"kind_ordinal_rule_subject_reason","duplicate_mode":"reject","no_items_impact":"unknown","default_review_priority":"normal","critical_enabled":false},"technical_rules":[{"category":"aaa","subcategory":"global","classification_rule":"aaa.global","rule_id":"risk.tech.aaa.v1","impact":"high"},{"category":"aaa","subcategory":"line_auth","classification_rule":"aaa.line_auth","rule_id":"risk.tech.aaa.v1","impact":"high"},{"category":"aaa","subcategory":"local_user","classification_rule":"aaa.local_user","rule_id":"risk.tech.aaa.v1","impact":"high"},{"category":"aaa","subcategory":"radius","classification_rule":"aaa.radius","rule_id":"risk.tech.aaa.v1","impact":"high"},{"category":"aaa","subcategory":"radius","classification_rule":"aaa.radius.context","rule_id":"risk.tech.aaa.v1","impact":"high"},{"category":"aaa","subcategory":"tacacs","classification_rule":"aaa.tacacs","rule_id":"risk.tech.aaa.v1","impact":"high"},{"category":"aaa","subcategory":"tacacs","classification_rule":"aaa.tacacs.context","rule_id":"risk.tech.aaa.v1","impact":"high"},{"category":"access_control","subcategory":"acl","classification_rule":"access_control.acl","rule_id":"risk.tech.access_control.v1","impact":"high"},{"category":"access_control","subcategory":"acl","classification_rule":"access_control.acl.context","rule_id":"risk.tech.access_control.v1","impact":"high"},{"category":"access_control","subcategory":"acl_binding","classification_rule":"access_control.acl_binding","rule_id":"risk.tech.access_control.v1","impact":"high"},{"category":"access_control","subcategory":"control_plane","classification_rule":"access_control.control_plane","rule_id":"risk.tech.access_control.v1","impact":"high"},{"category":"access_control","subcategory":"control_plane","classification_rule":"access_control.control_plane.context","rule_id":"risk.tech.access_control.v1","impact":"high"},{"category":"access_control","subcategory":"object_group","classification_rule":"access_control.object_group","rule_id":"risk.tech.access_control.v1","impact":"high"},{"category":"access_control","subcategory":"object_group","classification_rule":"access_control.object_group.context","rule_id":"risk.tech.access_control.v1","impact":"high"},{"category":"crypto_vpn","subcategory":"crypto_map","classification_rule":"crypto_vpn.crypto_map","rule_id":"risk.tech.crypto_vpn.v1","impact":"high"},{"category":"crypto_vpn","subcategory":"crypto_map","classification_rule":"crypto_vpn.crypto_map.context","rule_id":"risk.tech.crypto_vpn.v1","impact":"high"},{"category":"crypto_vpn","subcategory":"generic","classification_rule":"crypto_vpn.generic","rule_id":"risk.tech.crypto_vpn.v1","impact":"high"},{"category":"crypto_vpn","subcategory":"ike_isakmp","classification_rule":"crypto_vpn.ike_isakmp","rule_id":"risk.tech.crypto_vpn.v1","impact":"high"},{"category":"crypto_vpn","subcategory":"ike_isakmp","classification_rule":"crypto_vpn.ike_isakmp.context","rule_id":"risk.tech.crypto_vpn.v1","impact":"high"},{"category":"crypto_vpn","subcategory":"ipsec","classification_rule":"crypto_vpn.ipsec","rule_id":"risk.tech.crypto_vpn.v1","impact":"high"},{"category":"crypto_vpn","subcategory":"ipsec","classification_rule":"crypto_vpn.ipsec.context","rule_id":"risk.tech.crypto_vpn.v1","impact":"high"},{"category":"crypto_vpn","subcategory":"tunnel","classification_rule":"crypto_vpn.tunnel","rule_id":"risk.tech.crypto_vpn.v1","impact":"high"},{"category":"other","subcategory":"unclassified","classification_rule":"fallback.unclassified","rule_id":"risk.tech.unknown_item.v1","impact":"unknown"},{"category":"interface","subcategory":"addressing","classification_rule":"interface.addressing","rule_id":"risk.te