-- All source columns and the exact item set are immutable after any assessment,
-- including an eligible zero-item assessment. Guard both replacement identities.
CREATE TRIGGER change_risk_source_item_no_insert BEFORE INSERT ON change_event_items
WHEN EXISTS(SELECT 1 FROM change_risk_assessments a WHERE a.event_id=NEW.change_event_id)
 OR EXISTS(SELECT 1 FROM change_event_items i JOIN change_risk_assessments a ON a.event_id=i.change_event_id WHERE i.id=NEW.id)
BEGIN SELECT RAISE(ABORT,'immutable assessed risk source'); END;
CREATE TRIGGER change_risk_source_item_no_update BEFORE UPDATE ON change_event_items
WHEN EXISTS(SELECT 1 FROM change_risk_assessments WHERE event_id=OLD.change_event_id OR event_id=NEW.change_event_id)
 OR EXISTS(SELECT 1 FROM change_event_items i JOIN change_risk_assessments a ON a.event_id=i.change_event_id WHERE i.id=NEW.id)
BEGIN SELECT RAISE(ABORT,'immutable assessed risk source'); END;
CREATE TRIGGER change_risk_source_item_no_delete BEFORE DELETE ON change_event_items
WHEN EXISTS(SELECT 1 FROM change_risk_assessments WHERE event_id=OLD.change_event_id)
BEGIN SELECT RAISE(ABORT,'immutable assessed risk source'); END;
CREATE TRIGGER change_risk_source_event_no_insert BEFORE INSERT ON change_events
WHEN EXISTS(SELECT 1 FROM change_events e JOIN change_risk_assessments a ON a.event_id=e.id WHERE e.id=NEW.id OR e.to_backup_id=NEW.to_backup_id)
BEGIN SELECT RAISE(ABORT,'immutable assessed risk source identity'); END;
CREATE TRIGGER change_risk_source_event_no_delete BEFORE DELETE ON change_events
WHEN EXISTS(SELECT 1 FROM change_risk_assessments WHERE event_id=OLD.id)
BEGIN SELECT RAISE(ABORT,'immutable assessed risk source'); END;
CREATE TRIGGER change_risk_source_event_no_update BEFORE UPDATE ON change_events
WHEN (EXISTS(SELECT 1 FROM change_risk_assessments WHERE event_id=OLD.id)
AND (NEW.id IS NOT OLD.id OR NEW.device_id IS NOT OLD.device_id OR NEW.config_type IS NOT OLD.config_type
 OR NEW.from_backup_id IS NOT OLD.from_backup_id OR NEW.to_backup_id IS NOT OLD.to_backup_id
 OR NEW.detected_at IS NOT OLD.detected_at OR NEW.created_at IS NOT OLD.created_at
 OR NEW.analysis_version IS NOT OLD.analysis_version OR NEW.analyzed_at IS NOT OLD.analyzed_at
 OR NEW.item_count IS NOT OLD.item_count OR NEW.added_lines IS NOT OLD.added_lines OR NEW.removed_lines IS NOT OLD.removed_lines))
OR EXISTS(SELECT 1 FROM change_events e JOIN change_risk_assessments a ON a.event_id=e.id WHERE e.id<>OLD.id AND (e.id=NEW.id OR e.to_backup_id=NEW.to_backup_id))
BEGIN SELECT RAISE(ABORT,'immutable assessed risk source'); END;

INSERT INTO permissions(id,name,description) VALUES
 ('changes.risk.read','changes.risk.read','Read scoped immutable risk assessment history'),
 ('changes.risk.evaluate','changes.risk.evaluate','Preview and explicitly record scoped risk assessments');
INSERT INTO role_permissions(role_id,permission_id)
SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE
 (r.name='network_operator' AND p.name='changes.risk.read') OR
 (r.name IN ('network_administrator','system_administrator') AND p.name IN ('changes.risk.read','changes.risk.evaluate'));

